(() => {
 'use strict';if(!document.body.dataset.page?.includes('lens'))return;
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],T=window.Tom;
 const archive=document.createElement('section');archive.id='archive';archive.className='premium-section';archive.innerHTML=`<div class="section-heading reveal"><div><span class="eyebrow">THE PHOTO ARCHIVE / LOOK CLOSER</span><h2>Every frame<br><span class="muted">has a backstory.</span></h2></div><p>Open a study. Read the details.<br>Bring in your own frames to try the viewer.</p></div><div class="premium-toolbar"><label class="file-button">Add photos to this device<input type="file" id="archive-upload" accept="image/jpeg,image/png,image/webp" multiple></label><button id="archive-export">Export local photo notes</button></div><p class="fine-print">The three starter studies use the same credited reference image. Tom’s original photographs haven’t been added here yet. Imported photos and notes remain in this browser only; they do not publish to the website. Up to 12 photos, 20 MB each.</p><div class="archive-filter" aria-label="Filter the archive">${['All','Reference','Wildlife','Automotive','Landscape','Event','Personal'].map((x,i)=>`<button class="pill-button ${i===0?'active':''}" data-archive-filter="${x}">${x}</button>`).join('')}</div><div class="archive-grid" id="archive-grid"></div><p id="archive-status" class="fine-print" role="status"></p>`;
 $('#camera-simulator').after(archive);
 const studies=[{id:'reference-natural',title:'The quiet between ridgelines',category:'Reference',url:'/landscape.jpg',filter:'none',story:'A reference study of mist, forest, and distance in the Adirondacks. Use it to explore how framing and color change a scene.',location:'Adirondacks, New York',credit:'Wilder With You — Lake Placid weekend guide',reference:true},{id:'reference-cinema',title:'A colder kind of quiet',category:'Reference',url:'/landscape.jpg',filter:'saturate(.5) contrast(1.2) hue-rotate(8deg)',story:'The same photograph with a restrained color treatment. This study is about atmosphere—not a separate shoot.',location:'Adirondacks, New York',credit:'Reference image / alternate color study',reference:true},{id:'reference-mono',title:'Light without the color',category:'Reference',url:'/landscape.jpg',filter:'grayscale(1) contrast(1.2)',story:'Removing color shifts attention toward layers, shapes, and the bright mist over the trees. Compare it with the original.',location:'Adirondacks, New York',credit:'Reference image / monochrome study',reference:true}];
 let local=[],filter='All',current=null,original=false,db=null,dbOK=true;
 const viewer=T.modal('photo-viewer','A closer look.','<div id="photo-viewer-content"></div>','archive-viewer');
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function all(){return [...studies,...local]}function selected(){return all().filter(p=>filter==='All'||p.category===filter)}
 function render(){const entries=selected();$('#archive-grid').innerHTML=entries.map(p=>`<button class="archive-card" data-photo="${esc(p.id)}"><img src="${esc(p.url)}" alt="${esc(p.title)}" style="filter:${p.reference?p.filter:'none'}" loading="lazy"><span><strong>${esc(p.title)}</strong><small>${esc(p.category.toUpperCase())} / ${p.reference?'REFERENCE STUDY':'ON THIS DEVICE'}</small></span></button>`).join('');if(!entries.length)$('#archive-grid').innerHTML='<div class="archive-empty">No photographs in this category yet. Add a photo and choose its category in the viewer.</div>';$$('[data-photo]').forEach(b=>b.onclick=()=>show(b.dataset.photo));$('#archive-status').textContent=`${entries.length} frame${entries.length===1?'':'s'} shown · ${local.length} local photo${local.length===1?'':'s'}${!dbOK?' · Browser storage unavailable; imports last for this visit.':''}`;}
 function show(id){current=all().find(p=>p.id===id);if(!current)return;original=false;const p=current;$('#photo-viewer-content').innerHTML=`<div class="archive-lightbox"><div><img id="archive-full-image" src="${esc(p.url)}" alt="${esc(p.title)}" style="filter:${p.reference?p.filter:'none'}"><div class="archive-prev-next"><button class="outline-button" id="photo-previous">← Previous</button><button class="outline-button" id="photo-next">Next →</button></div></div><aside><span class="eyebrow">${esc(p.category)} / ${p.reference?'REFERENCE':'LOCAL PHOTO'}</span><h3>${esc(p.title)}</h3><p>${esc(p.story||'Add the story behind this frame in the details below.')}</p><dl class="archive-meta">${[['Camera',p.camera],['Lens',p.lens],['Aperture',p.aperture],['Shutter',p.shutter],['ISO',p.iso],['Focal length',p.focal],['Location',p.location]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Not provided')}</dd></div>`).join('')}</dl><div class="premium-toolbar"><button id="photo-compare" ${p.reference?'':'disabled'}>Show original</button><button id="photo-edit">Open in darkroom ↗</button></div><p class="archive-source">${p.reference?'<a href="https://www.wilderwithyou.com/blog/how-to-spend-2-days-in-lake-placid-new-york-the-perfect-weekend-itinerary" target="_blank" rel="noopener noreferrer">'+esc(p.credit)+' ↗</a>': 'Imported on this device. Metadata is entered by you; it is not automatically extracted.'}</p></aside></div>${p.reference?'':`<details><summary>Edit local photo notes</summary><form id="photo-notes" class="metadata-editor">${[['title','Title'],['camera','Camera'],['lens','Lens'],['aperture','Aperture'],['shutter','Shutter speed'],['iso','ISO'],['focal','Focal length'],['location','Broad location']].map(([k,v])=>`<label>${v}<input name="${k}" value="${esc(p[k]||'')}" maxlength="120" ${k==='title'?'required':''}></label>`).join('')}<label>Category<select name="category">${['Wildlife','Automotive','Landscape','Event','Personal'].map(x=>`<option${p.category===x?' selected':''}>${x}</option>`).join('')}</select></label><label class="full">Story<textarea name="story" maxlength="1500">${esc(p.story||'')}</textarea></label><button type="submit" class="outline-button full">Save notes on this device</button></form></details>`}`;
 const related=all().filter(x=>x.id!==id&&x.category===p.category).slice(0,3);if(related.length){const row=document.createElement('div');row.className='premium-toolbar';row.style.marginTop='25px';row.innerHTML='<span class="small-caps">RELATED FRAMES</span>';related.forEach(r=>{const b=document.createElement('button');b.textContent=r.title;b.onclick=()=>show(r.id);row.append(b)});$('#photo-viewer-content').append(row)}
 $('#photo-compare').onclick=()=>{original=!original;$('#archive-full-image').style.filter=original?'none':p.filter;$('#photo-compare').textContent=original?'Return to study':'Show original'};$('#photo-edit').onclick=()=>{viewer.close();window.TomDarkroom?.openImage(p.url);$('#darkroom').scrollIntoView({behavior:T.motion()?'smooth':'auto'})};$('#photo-previous').onclick=()=>step(-1);$('#photo-next').onclick=()=>step(1);if($('#photo-notes'))$('#photo-notes').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));Object.assign(p,values);await save(p);render();show(p.id);T.notify('Photo notes saved on this device.')};T.open(viewer);}
 function step(direction){const list=selected(),i=list.findIndex(p=>p.id===current?.id);if(list.length)show(list[(i+direction+list.length)%list.length].id)}viewer.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select'))return;if(e.key==='ArrowLeft'){e.preventDefault();step(-1)}if(e.key==='ArrowRight'){e.preventDefault();step(1)}});
 $$('[data-archive-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.archiveFilter;$$('[data-archive-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});
 function openDB(){return new Promise(resolve=>{if(!window.indexedDB){dbOK=false;resolve();return}const req=indexedDB.open('focused-on-tom-photos',1);req.onupgradeneeded=()=>req.result.createObjectStore('photos',{keyPath:'id'});req.onsuccess=()=>{db=req.result;resolve()};req.onerror=()=>{dbOK=false;resolve()};req.onblocked=()=>{dbOK=false;resolve()}})}
 async function save(p){if(!db)return;return new Promise(resolve=>{const tx=db.transaction('photos','readwrite');const {url,...record}=p;tx.objectStore('photos').put(record);tx.oncomplete=resolve;tx.onerror=()=>{dbOK=false;T.notify('Browser storage is full. This photo stays available for this visit.');resolve()}})}
 $('#archive-upload').onchange=async e=>{const files=[...e.target.files];for(const f of files){if(local.length>=12){T.notify('The local archive holds up to 12 photos.');break}if(f.size>20*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){T.notify('Use JPG, PNG, or WebP images under 20 MB.');continue}const url=URL.createObjectURL(f);const valid=await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(true);im.onerror=()=>resolve(false);im.src=url});if(!valid){URL.revokeObjectURL(url);T.notify('One image could not be opened.');continue}const p={id:crypto.randomUUID(),title:f.name.replace(/\.[^.]+$/,''),category:'Personal',blob:f,url,story:'',location:''};local.push(p);await save(p)}filter='All';$$('[data-archive-filter]').forEach(b=>b.classList.toggle('active',b.dataset.archiveFilter==='All'));render();e.target.value='';};
 $('#archive-export').onclick=()=>{const notes=local.map(({url,blob,...p})=>p),data=new Blob([JSON.stringify(notes,null,2)],{type:'application/json'}),url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='focused-on-tom-photo-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);T.notify('Photo notes exported. Original image files are not included.')};
 openDB().then(()=>{if(!db){render();return}const req=db.transaction('photos').objectStore('photos').getAll();req.onsuccess=()=>{local=req.result.slice(0,12).map(p=>({...p,url:URL.createObjectURL(p.blob)}));render()};req.onerror=()=>{dbOK=false;render()}});render();T.reveal();
})();
